const raw = $input.first().json;
let rpc = raw;
if (typeof raw?.data === 'string') {
  const dataLine = raw.data.split('\n').find((line) => line.startsWith('data: '));
  rpc = JSON.parse(dataLine ? dataLine.slice(6) : raw.data);
}
const text = rpc?.result?.content?.[0]?.text;
if (!text) {
  throw new Error('Dealport MCP did not return preview_companies content.');
}
const preview = JSON.parse(text);
return [{
  json: {
    summary: `Found ${preview.matching_count} matching US private companies ($0.00 preview).`,
    matching_count: preview.matching_count,
    tam_gate_passed: preview.tam_gate_passed,
    cost_usd: preview.cost_usd,
    sample_companies: preview.sample,
    docs: 'https://dealport.com/docs',
    mcp_registry: 'https://registry.modelcontextprotocol.io/v0.1/servers/com.dealport%2Fdealport/versions/latest'
  }
}];
